<div><?php require __DIR__.'/../includes/leader_sidebar.php';?><main class="main"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-btn" data-sidebar-toggle><i class="bi bi-list"></i></button><div><h1>Pastor Messages</h1><p>Receive pastoral communication and church direction directly from the Pastor.</p></div></div><span class="live-pill">Pastoral communication</span></header><div class="content"><div class="cardx p-4"><div class="d-grid gap-3"><?php foreach($rows as $r):?><article class="p-4 rounded-4 border"><div class="d-flex justify-content-between gap-3 flex-wrap"><div><span class="badge-soft"><?=e(event_category_label($r['type']))?></span><h3 class="mt-2 mb-1"><?=e($r['title'])?></h3><div class="small text-muted">From <?=e($r['pastor_name'])?> · <?=e(date('d M Y, g:i A',strtotime($r['published_at']?:$r['created_at'])))?></div></div><span class="badge text-bg-<?=($r['priority']==='urgent'?'danger':($r['priority']==='important'?'warning':'secondary'))?>"><?=e(ucfirst($r['priority']))?></span></div><p class="mt-3 mb-0" style="white-space:pre-wrap"><?=e($r['message'])?></p></article><?php endforeach;?><?php if(!$rows):?><div class="empty">No pastoral messages have been published yet.</div><?php endif;?></div></div></div></main></div>
